param([Parameter(Mandatory=$true)][string]$MigrationPath,[switch]$AddressSanitizer,[switch]$VerifyLive)
$ErrorActionPreference='Stop';$repo=[IO.Path]::GetFullPath("$PSScriptRoot/../..");$out="$repo/build-extractors/runtime-test/kingslayers-pickup-data"
& "$PSScriptRoot/Invoke-WithRuntimeDiagnostics.ps1" -EvidenceDirectory $out -RuntimeDirectories $out -Test {
 $migration=Get-Content $MigrationPath -Raw
 $cf='(SourceTypeOrReferenceId=4 AND SourceGroup=251107) OR(SourceTypeOrReferenceId=17 AND SourceEntry IN(215112,215113,215114))'
 $filters=[ordered]@{gameobject_template='entry IN(251107,249347)';gameobject_loot_template='Entry IN(251107,249347)';conditions="$cf OR(SourceTypeOrReferenceId=4 AND SourceGroup=249347)";smart_scripts='entryorguid IN(251107,108222,108367)'}
 $setup='SET SESSION group_concat_max_len=1048576;';foreach($t in $filters.Keys){$setup+="CREATE TEMPORARY TABLE saved_$t LIKE $t;INSERT INTO saved_$t SELECT * FROM $t WHERE $($filters[$t]);CREATE TEMPORARY TABLE $t LIKE saved_$t;INSERT INTO $t SELECT * FROM saved_$t;"}
 $normalize="UPDATE gameobject_template SET Data1=0 WHERE entry=251107;DELETE FROM conditions WHERE $cf;";$setup+=$normalize
 $db=(Get-Content "$repo/build-extractors/bin/Release/worldserver.conf"|Where-Object {$_ -match '^WorldDatabaseInfo\s*='}).Split('"')[1].Split(';');$number=0
 function Query([string]$sql,[switch]$Expected){$script:number++;$stderr="$out/sql-stderr-$script:number.txt";$prior=$env:MYSQL_PWD;$old=$ErrorActionPreference;try{$env:MYSQL_PWD=$db[3];$ErrorActionPreference='Continue';$rows=@($sql|& C:/wamp64/bin/mariadb/mariadb11.4.9/bin/mysql.exe --host=$($db[0]) --port=$($db[1]) --user=$($db[2]) --database=$($db[4]) --batch --raw --skip-column-names --force 2> $stderr);$code=$LASTEXITCODE}finally{$env:MYSQL_PWD=$prior;$ErrorActionPreference=$old};$err=Get-Content $stderr -Raw;if($Expected){if($err -notmatch '1644 \(45000\)' -or @($err -split "`n"|Where-Object {$_ -match '^ERROR '}).Count -ne 1){throw 'Expected Kingslayers refusal missing'}}elseif($code -or $err){throw 'Kingslayers TEMP/readonly query failed'};$rows}
 function Snapshot([string]$label){($filters.Keys|ForEach-Object {"SELECT '$label-$_',a.* FROM $_ a;"}) -join "`n"}
 function Rows($rows,[string]$label){@($rows|Where-Object {$_ -like "$label`t*"}|ForEach-Object {$_.Substring($label.Length+1)}|Sort-Object -CaseSensitive)}
 function Signature($rows,[string]$label){(Rows $rows $label) -join "`n"}
 $predicates="SELECT 'loot',ElseGroup,ConditionTypeOrReference,ConditionTarget,ConditionValue1,ConditionValue2,ConditionValue3,NegativeCondition FROM conditions WHERE SourceTypeOrReferenceId=4 AND SourceGroup=251107;SELECT 'cast',ElseGroup,ConditionTypeOrReference,ConditionTarget,ConditionValue1,ConditionValue2,ConditionValue3,NegativeCondition FROM conditions WHERE SourceTypeOrReferenceId=17 AND SourceEntry=215112;"
 $r=Query "$setup $(Snapshot 'original') SET SESSION group_concat_max_len=32; $migration SELECT 'limit',@@SESSION.group_concat_max_len; $(Snapshot 'first') $migration $(Snapshot 'second') $predicates $normalize $(Snapshot 'normalized')"
 foreach($t in $filters.Keys){if((Signature $r "first-$t") -cne (Signature $r "second-$t")){throw 'Kingslayers migration not idempotent'};if((Signature $r "original-$t") -cne (Signature $r "normalized-$t")){throw "Unrelated Kingslayers data changed: $t"}}
 if($r -notcontains "limit`t32"){throw 'Aggregation limit not restored'}
 foreach($kind in @('loot','cast')){[IO.File]::WriteAllLines("$out/$kind.tsv",[string[]](Rows $r $kind))}
 $changes=@("UPDATE gameobject_template SET ScriptName='custom' WHERE entry=251107;",'UPDATE gameobject_template SET Data1=1 WHERE entry=251107;','UPDATE gameobject_template SET Data0=1691 WHERE entry=251107;','UPDATE gameobject_loot_template SET Chance=50 WHERE Entry=251107;','DELETE FROM gameobject_loot_template WHERE Entry=251107;',"INSERT INTO conditions(SourceTypeOrReferenceId,SourceGroup,SourceEntry,ConditionTypeOrReference,ConditionValue1) VALUES(17,0,215112,15,1);", "INSERT INTO conditions(SourceTypeOrReferenceId,SourceGroup,SourceEntry,ConditionTypeOrReference,ConditionValue1) VALUES(4,251107,128870,15,1);")
 foreach($applied in @($false,$true)){$prior=if($applied){$migration}else{''};foreach($change in $changes){$r=Query "$setup $prior $change $(Snapshot 'before') $migration $(Snapshot 'after')" -Expected;foreach($t in $filters.Keys){if((Signature $r "before-$t") -cne (Signature $r "after-$t")){throw 'Refused Kingslayers migration mutated data'}}}}
 if($VerifyLive){$sha=[Security.Cryptography.SHA1]::Create();try{$hash=[BitConverter]::ToString($sha.ComputeHash([Text.Encoding]::UTF8.GetBytes(([IO.File]::ReadAllText((Resolve-Path $MigrationPath))).Replace("`r`n","`n")))).Replace('-','')}finally{$sha.Dispose()};$r=Query "SET SESSION TRANSACTION READ ONLY;SET SESSION group_concat_max_len=1048576;SELECT 'update',hash,state FROM updates WHERE name='2026_10_27_14_kingslayers_native_pickup.sql';SELECT 'link',Data1 FROM gameobject_template WHERE entry=251107;SELECT 'conditions',COUNT(*) FROM conditions WHERE $cf;SELECT 'condition-hash',SHA2(GROUP_CONCAT(CONCAT_WS('|',SourceTypeOrReferenceId,SourceGroup,SourceEntry,SourceId,ElseGroup,ConditionTypeOrReference,ConditionTarget,ConditionValue1,ConditionValue2,ConditionValue3,NegativeCondition,ErrorTextId,ScriptName,Comment) ORDER BY SourceTypeOrReferenceId,SourceGroup,SourceEntry,SourceId,ElseGroup,ConditionTypeOrReference,ConditionTarget,ConditionValue1,ConditionValue2,ConditionValue3,NegativeCondition,ErrorTextId,ScriptName,Comment SEPARATOR '\n'),256) FROM conditions WHERE $cf;";foreach($row in @("update`t$hash`tRELEASED","link`t251107","conditions`t196","condition-hash`t633f0a074dc50580d8a4de86cbbf96f7b9082c8b7b188f44e0e7a28abdfc9aad")){if($r -notcontains $row){throw 'Live Kingslayers updater/data differs'}}}
 function Section([string]$s,[string]$a,[string]$b){$first=$s.IndexOf($a);$last=$s.IndexOf($b,[Math]::Max(0,$first));if($first -lt 0 -or $last -le $first){throw "Missing native $a"};$s.Substring($first,$last-$first)}
 $source=Get-Content "$repo/src/server/game/Conditions/ConditionMgr.cpp" -Raw
 $cases='';foreach($pair in @(@('CONDITION_ITEM:','CONDITION_ITEM_EQUIPPED:'),@('CONDITION_CLASS:','CONDITION_RACE:'),@('CONDITION_QUESTREWARDED:','CONDITION_QUEST_NONE:'),@('CONDITION_MAPID:','CONDITION_AREAID:'),@('CONDITION_SCENARION_STEP:','CONDITION_REALM_ACHIEVEMENT:'),@('CONDITION_ALIVE:','CONDITION_HP_VAL:'))){$cases+=Section $source ('        case '+$pair[0]) ('        case '+$pair[1])}
 [IO.File]::WriteAllText("$out/Conditions.inc",$cases)
 [IO.File]::WriteAllText("$out/ElseGroups.inc",(Section $source 'bool ConditionMgr::IsObjectMeetToConditionList(' 'bool ConditionMgr::IsObjectMeetToConditions(WorldObject* object,'))
 $source=Get-Content "$repo/src/server/game/Loot/LootMgr.cpp" -Raw
 [IO.File]::WriteAllText("$out/LootCondition.inc",(Section $source 'bool LootItem::AllowedForPlayer(Player const* player) const' 'void LootItem::AddAllowedLooter('))
 $recheck=Section $source '    if (item && !AllowedForPlayer(player,' 'uint32 Loot::GetMaxSlotInLootFor('
 [IO.File]::WriteAllText("$out/SlotRecheck.inc",$recheck.Substring(0,$recheck.LastIndexOf('}')))
 $source=Get-Content "$repo/src/server/game/Entities/GameObject/GameObjectData.cpp" -Raw
 [IO.File]::WriteAllText("$out/GetLootId.inc",(Section $source 'uint32 GameObjectTemplate::GetLootId() const' 'uint32 GameObjectTemplate::GetGossipMenuId() const'))
 $vs=& "${env:ProgramFiles(x86)}/Microsoft Visual Studio/Installer/vswhere.exe" -latest -products '*' -requires Microsoft.VisualStudio.Component.VC.Tools.x86.x64 -property installationPath
 $asan=if($AddressSanitizer){'/fsanitize=address /Zi'}else{''}
 [IO.File]::WriteAllText("$out/run.cmd","@echo off`ncall `"$vs/VC/Auxiliary/Build/vcvars64.bat`" >nul`ncd /d `"$out`"`ncl /nologo /EHsc /std:c++17 /W4 $asan /I`"$out`" `"$PSScriptRoot/KingslayersPickupConditionsTest.cpp`" /Fe:test.exe /Fo:test.obj`nif errorlevel 1 exit /b 1`ntest.exe loot.tsv cast.tsv`nexit /b %errorlevel%`n")
 & "$out/run.cmd";if($LASTEXITCODE){throw 'Native Kingslayers condition regression failed'}
 'PASS four TEMP tables/repeat/full-field preservation/14 custom refusals/low aggregation limit and native cached-loot/cast predicates; no character writes'
}
